head.script:
scwin.count=0;
scwin.onpageload = function () {
    requires("uiplugin.popup");
};

scwin.onpageunload = function () {

};


scwin.trigger1_onclick = function (e) {
    scwin.count++;
    const tmpSrc = scwin.getfolderPath() + "/popUp_content.xml";
    var options = {
        id: scwin.count,
        type: "browserPopup",
        width: "400px",
        height: "200px",
        top: "100px",
        left: "200px",
        popupName: "Modal Popup - browser",
        modal: "true",
        resizable: true
    };
    $p.openPopup(tmpSrc, options);
};

